const { useState } = React;

function Profile() {
  const [name] = useState('민수');
  const [count, setCount] = useState(0);

  return (
    <section>
      <p>{name}: {count}</p>
      <button type="button" onClick={() => setCount(count + 1)}>증가</button>
    </section>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<Profile />);

